async function main(ctx) {
  const input = ctx.input || {};

  const query = String(input.query ?? '').trim();
  if (!query) throw new Error('Missing required argument: query');

  const limitRaw = Number(input.limit ?? 5);
  const limit = Number.isFinite(limitRaw) ? Math.min(10, Math.max(1, Math.floor(limitRaw))) : 5;

  const offsetRaw = Number(input.offset ?? 0);
  const offset = Number.isFinite(offsetRaw) ? Math.max(0, Math.floor(offsetRaw)) : 0;

  const gl = String(input.gl ?? 'us').trim() || 'us';
  const hl = String(input.hl ?? 'en').trim() || 'en';

  const timeoutMsRaw = Number(input.timeoutMs ?? 30000);
  const timeout = Number.isFinite(timeoutMsRaw) ? Math.max(1000, Math.floor(timeoutMsRaw)) : 30000;

  const maxHtmlCharsRaw = Number(input.maxHtmlChars ?? 1000000);
  const maxHtmlCharsUnclamped = Number.isFinite(maxHtmlCharsRaw) ? Math.max(0, Math.floor(maxHtmlCharsRaw)) : 1000000;
  const maxHtmlChars = Math.min(2000000, maxHtmlCharsUnclamped);

  // Keep for compatibility/debug (not strictly required for system.webSearch)
  const params = new URLSearchParams();
  params.set('q', query);
  if (offset) params.set('start', String(offset));
  if (hl) params.set('hl', hl);
  if (gl) params.set('gl', gl);
  params.set('safe', 'active');
  params.set('pws', '0');
  const url = 'https://www.google.com/search?' + params.toString();

  // Prefer platform system connector for search; ask for structured output.
  const systemArgs = {
    q: query,
    engine: 'google',
    hl,
    gl,
    num: limit,
    start: offset,
    format: 'json',
    dataFormat: 'parsed_light'
    // url: optional override if needed
  };

  return { query, limit, offset, gl, hl, timeout, maxHtmlChars, url, systemArgs };
}

async function main(ctx) {
  const resp = ctx.input || {};
  const prep = ctx.lastOutputOf('build_url') || {};

  const status = Number(resp.status ?? 0);
  if (Number.isFinite(status) && status >= 400) {
    const statusText = String(resp.statusText ?? '').trim();
    let bodySnippet = '';
    try {
      bodySnippet = typeof resp.body === 'string' ? resp.body : JSON.stringify(resp.body);
    } catch (_) {
      bodySnippet = String(resp.body ?? '');
    }
    bodySnippet = String(bodySnippet).slice(0, 240);

    if (status === 401 || status === 403) {
      throw new Error(
        `system.webSearch unauthorized (${status}${statusText ? ' ' + statusText : ''}). ` +
          `Platform secrets for the system connector may be missing. Body: ${bodySnippet}`
      );
    }

    throw new Error(
      `system.webSearch failed: ${status}${statusText ? ' ' + statusText : ''} | body: ${bodySnippet}`
    );
  }

  const limit = Number(prep.limit ?? 5);

  function decodeEntities(s) {
    if (s == null) return null;
    return String(s)
      .replace(/&nbsp;/gi, ' ')
      .replace(/&amp;/gi, '&')
      .replace(/&lt;/gi, '<')
      .replace(/&gt;/gi, '>')
      .replace(/&quot;/gi, '"')
      .replace(/&#39;/gi, "'")
      .replace(/&#(\d+);/g, (_, n) => {
        const code = Number(n);
        return Number.isFinite(code) ? String.fromCharCode(code) : _;
      });
  }

  function stripTags(s) {
    return String(s || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  }

  function getHostname(u) {
    try {
      return new URL(u).hostname;
    } catch (_) {
      return null;
    }
  }

  function safeAbsoluteUrl(u) {
    const raw = String(u || '');
    if (!raw) return null;
    try {
      const dec = decodeURIComponent(raw);
      if (/^https?:\/\//i.test(dec)) return dec;
    } catch (_) {}
    if (/^https?:\/\//i.test(raw)) return raw;
    return null;
  }

  function fromGoogleRedirectHref(href) {
    const s = String(href || '');
    const m1 = /[?&]q=([^&]+)/.exec(s);
    if (m1) return safeAbsoluteUrl(m1[1]);
    const m2 = /[?&]url=([^&]+)/.exec(s);
    if (m2) return safeAbsoluteUrl(m2[1]);
    return null;
  }

  function normalizeSnippetText(text) {
    let t = String(text || '').replace(/\s+/g, ' ').trim();
    if (!t) return null;

    // Strip leading date/relative-time prefixes when followed by a dash.
    const datePrefix = new RegExp(
      '^(?:' +
        '(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Sept|Oct|Nov|Dec)\\s+\\d{1,2},\\s+\\d{4}' +
        '|(?:\\d{4})' +
        '|(?:\\d+\\s+(?:day|week|month|year)s?\\s+ago)' +
      ')\\s*(?:—|–|-)\\s*',
      'i'
    );
    t = t.replace(datePrefix, '').trim();

    return t || null;
  }

  function looksLikeDateOnlyOrMetadata(text) {
    const t = String(text || '').replace(/\s+/g, ' ').trim();
    if (!t) return true;

    const words = t.split(' ').filter(Boolean);
    const wc = words.length;

    if (wc <= 3) return true;

    const monthDate = /\b(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Sept|Oct|Nov|Dec)\b\s+\d{1,2},\s+\d{4}\b/i;
    const relative = /\b\d+\s+(?:day|week|month|year)s?\s+ago\b/i;
    const yearOnly = /^(?:19|20)\d{2}$/;

    if (monthDate.test(t) && wc <= 4) return true;
    if (relative.test(t) && wc <= 4) return true;
    if (yearOnly.test(t)) return true;

    return false;
  }

  function cleanSnippet(s) {
    const n = normalizeSnippetText(s);
    if (!n) return null;
    const clipped = n.slice(0, 400);
    if (looksLikeDateOnlyOrMetadata(clipped)) return null;
    return clipped;
  }

  // -----------------
  // Path A: structured JSON from system.webSearch
  // -----------------
  const body = resp.body;

  function pickArray(b) {
    if (!b || typeof b !== 'object') return null;
    return (
      b.results ||
      b.organic_results ||
      b.organicResults ||
      b.items ||
      b.organic ||
      (b.data && (b.data.results || b.data.organic_results || b.data.items))
    );
  }

  const arrMaybe = Array.isArray(body) ? body : pickArray(body);

  const candidates = [];
  const seen = new Set();

  function push(url, title, snippet, displayLink) {
    if (!url) return;
    if (seen.has(url)) return;
    const host = displayLink || getHostname(url);
    if (!host) return;
    if (/google\./i.test(host)) return;
    if (host === 'webcache.googleusercontent.com') return;

    candidates.push({
      position: candidates.length + 1,
      title: title ? String(title).slice(0, 300) : null,
      url,
      snippet: cleanSnippet(snippet),
      displayLink: host
    });
    seen.add(url);
  }

  if (Array.isArray(arrMaybe)) {
    for (const item of arrMaybe) {
      if (!item || typeof item !== 'object') continue;
      const url = safeAbsoluteUrl(item.link || item.url || item.href);
      const title = item.title || item.name;
      const snippet = item.snippet || item.description || item.content || item.text;
      const displayLink = item.displayed_link || item.displayLink || item.source;
      if (url) push(url, title, snippet, displayLink);
      if (candidates.length >= limit) break;
    }

    return candidates.slice(0, limit).map((r, i) => ({ ...r, position: i + 1 }));
  }

  // -----------------
  // Path B: raw HTML fallback (if backend returns HTML/text)
  // -----------------
  const htmlRaw = typeof body === 'string' ? body : (typeof resp.body === 'string' ? resp.body : String(resp.body ?? ''));
  const html = htmlRaw.slice(0, Number(prep.maxHtmlChars ?? 1000000));

  function neighborhoodAround(idx) {
    const i = Number(idx);
    if (!Number.isFinite(i)) return '';
    const start = Math.max(0, i - 800);
    const end = Math.min(html.length, i + 6000);
    return html.slice(start, end);
  }

  function extractSnippetFromNeighborhood(neighborhoodHtml) {
    const h = String(neighborhoodHtml || '');

    const patterns = [
      /<(?:div|span)[^>]+class="[^"]*VwiC3b[^"]*"[^>]*>([\s\S]*?)<\/(?:div|span)>/gi,
      /<span[^>]+class="[^"]*aCOpRe[^"]*"[^>]*>([\s\S]*?)<\/span>/gi,
      /<div[^>]+class="[^"]*BNeawe[^"]*"[^>]*>([\s\S]*?)<\/div>/gi
    ];

    for (const re of patterns) {
      let m;
      while ((m = re.exec(h))) {
        const raw = decodeEntities(stripTags(m[1] || ''));
        const cleaned = cleanSnippet(raw);
        if (!cleaned) continue;
        return cleaned;
      }
    }

    return null;
  }

  // 1) Classic redirect links: /url?q=... or /url?url=...
  const reRedirect = /<a\s+[^>]*href="((?:https?:\/\/www\.google\.com)?\/url\?[^\"]+)"[^>]*>([\s\S]*?)<\/a>/gi;
  let m;
  while ((m = reRedirect.exec(html)) && candidates.length < limit * 10) {
    const finalUrl = fromGoogleRedirectHref(m[1]);
    if (!finalUrl) continue;

    let title = null;
    const h3 = /<h3[^>]*>([\s\S]*?)<\/h3>/i.exec(m[2] || '');
    if (h3) title = decodeEntities(stripTags(h3[1]));
    if (!title) title = decodeEntities(stripTags(m[2] || ''));

    const snippet = extractSnippetFromNeighborhood(neighborhoodAround(m.index));

    push(finalUrl, title, snippet, null);
  }

  // 2) Modern SERP pattern: <a href="https://..."> ... <h3>Title</h3> ... </a>
  const reDirectWithH3 = /<a\s+[^>]*href="(https?:\/\/[^"]+)"[^>]*>[\s\S]*?<h3[^>]*>([\s\S]*?)<\/h3>[\s\S]*?<\/a>/gi;
  while (candidates.length < limit && (m = reDirectWithH3.exec(html))) {
    const url = safeAbsoluteUrl(m[1]);
    const title = decodeEntities(stripTags(m[2] || ''));

    const snippet = extractSnippetFromNeighborhood(neighborhoodAround(m.index));

    push(url, title, snippet, null);
  }

  return candidates.slice(0, limit).map((r, i) => ({ ...r, position: i + 1 }));
}
